import { Schema, model, type Types } from 'mongoose';
import {
  LISTING_PURPOSES,
  PROPERTY_STATUSES,
  PROPERTY_TYPES,
  SIZE_UNITS,
  type ListingPurpose,
  type PropertyStatus,
  type PropertyType,
  type SizeUnit,
} from '@recrm/shared';
import { tenantFields, tenantGuardPlugin } from './plugins/tenant';
import { syncFields, syncIndexes, type SyncDoc } from './plugins/sync';

export interface PropertyDoc extends SyncDoc {
  _id: Types.ObjectId;
  businessId: Types.ObjectId;
  /** Human id, e.g. RE-000125. Generated by the API, unique per business. */
  propertyId: string;
  propertyType: PropertyType;
  listingPurpose: ListingPurpose;
  status: PropertyStatus;
  title?: string;
  area?: string;
  society?: string;
  block?: string;
  street?: string;
  plotNumber?: string;
  city?: string;
  size: number;
  sizeUnit: SizeUnit;
  sizeSqft: number;
  askingPrice: number;
  expectedFinalPrice?: number;
  minimumPrice?: number;
  negotiable: boolean;
  ownerId?: Types.ObjectId;
  description?: string;
  latitude?: number;
  longitude?: number;
  location?: { type: 'Point'; coordinates: [number, number] };
  googleMapsUrl?: string;
  bedrooms?: number;
  bathrooms?: number;
  floors?: number;
  coverImageUrl?: string;
  coverThumbnailUrl?: string;
  matchCount: number;
  statusChangedAt?: Date;
  /** When someone last confirmed with the owner that the listing is still on offer at this price. */
  lastVerifiedAt?: Date;
  lastVerifiedBy?: Types.ObjectId;
  searchText: string;
  createdBy: Types.ObjectId;
  updatedBy: Types.ObjectId;
  createdAt: Date;
  updatedAt: Date;
}

const schema = new Schema<PropertyDoc>(
  {
    ...tenantFields,
    ...syncFields,
    propertyId: { type: String, required: true, immutable: true },
    propertyType: { type: String, enum: PROPERTY_TYPES, required: true },
    listingPurpose: { type: String, enum: LISTING_PURPOSES, default: 'SALE' },
    status: { type: String, enum: PROPERTY_STATUSES, default: 'AVAILABLE' },
    title: { type: String, maxlength: 150 },
    area: { type: String, trim: true, maxlength: 120 },
    society: { type: String, trim: true, maxlength: 120 },
    block: { type: String, trim: true, maxlength: 60 },
    street: { type: String, trim: true, maxlength: 120 },
    plotNumber: { type: String, trim: true, maxlength: 60 },
    city: { type: String, trim: true, maxlength: 80 },
    size: { type: Number, required: true, min: 0 },
    sizeUnit: { type: String, enum: SIZE_UNITS, required: true },
    sizeSqft: { type: Number, required: true, min: 0 },
    askingPrice: { type: Number, required: true, min: 0 },
    expectedFinalPrice: { type: Number, min: 0 },
    minimumPrice: { type: Number, min: 0 },
    negotiable: { type: Boolean, default: true },
    ownerId: { type: Schema.Types.ObjectId, ref: 'PropertyOwner' },
    description: { type: String, maxlength: 5000 },
    latitude: Number,
    longitude: Number,
    location: {
      type: { type: String, enum: ['Point'] },
      coordinates: { type: [Number], default: undefined },
    },
    googleMapsUrl: String,
    bedrooms: { type: Number, min: 0 },
    bathrooms: { type: Number, min: 0 },
    floors: { type: Number, min: 0 },
    coverImageUrl: String,
    coverThumbnailUrl: String,
    matchCount: { type: Number, default: 0 },
    statusChangedAt: Date,
    lastVerifiedAt: Date,
    lastVerifiedBy: { type: Schema.Types.ObjectId, ref: 'User' },
    searchText: { type: String, default: '' },
  },
  { timestamps: true, versionKey: false },
);

syncIndexes(schema);
schema.index({ businessId: 1, propertyId: 1 }, { unique: true });
schema.index({ businessId: 1, deletedAt: 1, updatedAt: -1 });
schema.index({ businessId: 1, status: 1, listingPurpose: 1, propertyType: 1, askingPrice: 1 });
schema.index({ businessId: 1, society: 1, block: 1 });
schema.index({ businessId: 1, plotNumber: 1 });
schema.index({ businessId: 1, ownerId: 1 });
schema.index({ businessId: 1, status: 1, lastVerifiedAt: 1 });
schema.index({ businessId: 1, searchText: 1 });
schema.index({ location: '2dsphere' }, { sparse: true });
schema.plugin(tenantGuardPlugin);

export const Property = model<PropertyDoc>('Property', schema, 'properties');
